import { boot } from 'quasar/wrappers';
import { LocalStorage, date } from 'quasar';
import { de, fr, es, enUS, Locale } from 'date-fns/locale';
import { CONSTANTS, DEFAULT_LANGUAGE, date_pattern_setting } from 'src/constants';
import { formatDistanceToNow } from 'date-fns';
import pythonDateFormatToJs from 'src/utils/pythonDateFormatToJs';
import { useSettingStore } from 'src/store/Settings/setting.store';
import { safeBoot } from 'src/utils/bootSafety';

export function useFormattedTimeAgo(dateString: string | Date | null | undefined): string {
  if (!dateString) return '';

  try {
    const locale = getDateLocale();
    return formatDistanceToNow(new Date(dateString), { addSuffix: true, locale });
  } catch (error) {
    console.error('Error formatting time:', error);
    return '';
  }
}

// Absolute timestamp — companion to the relative label above. Formatted with
// the user's configured date pattern (Datum Muster, e.g. %d.%m.%Y) plus the
// time, unless the source is a bare YYYY-MM-DD date (then no time is shown).
export function useFormattedTimestamp(dateString: string | Date | null | undefined): string {
  if (!dateString) return '';

  try {
    const datePattern = userDatePattern();

    // Bare date: no real time, and must not be timezone-shifted.
    if (typeof dateString === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(dateString)) {
      return date.formatDate(`${dateString} 00:00:00`, datePattern);
    }

    // Assume UTC when the ISO string carries no timezone, then render local.
    const withZone =
      typeof dateString === 'string' && !/Z$|[+-]\d{2}:?\d{2}$/.test(dateString)
        ? dateString + 'Z'
        : dateString;
    return date.formatDate(new Date(withZone), `${datePattern} HH:mm:ss`);
  } catch (error) {
    console.error('Error formatting timestamp:', error);
    return '';
  }
}

// The user's Datum Muster (Python strftime) converted to a Quasar mask;
// empty preference falls back to the converter's own default.
function userDatePattern(): string {
  const pref = useSettingStore().user_settings[date_pattern_setting];
  return pythonDateFormatToJs.methods.convertPYDateFormatToJS(pref ? String(pref) : '');
}

function getDateLocale(): Locale {
  let locale: Locale = de;

  if (LocalStorage.has(CONSTANTS.selected_language)) {
    const selectedLanguage = LocalStorage.getItem(CONSTANTS.selected_language) as string;
    if (selectedLanguage === 'es-es') {
      locale = es;
    } else if (selectedLanguage === DEFAULT_LANGUAGE) {
      locale = enUS;
    } else if (selectedLanguage === 'fr-fr') {
      locale = fr;
    }
  }

  return locale;
}

export default boot(safeBoot('timeago', ({ app }) => {
  // Register useFormattedTimeAgo as a global property for backward compatibility
  app.config.globalProperties.$formatTimeAgo = useFormattedTimeAgo;
}));
